import type { ChartLegendItem } from 'components';
import {
  DEFAULT_LINE_BAR_CHART_COLORS,
  getSeriesColorByLabel,
  isBudgetSeriesLabel,
} from 'components/Chart/lineBarChart';

const DEFAULT_PHI_CHART_LEGEND_LABELS = [
  'Last year',
  'Budget',
  'Current quarter',
] as const;

export function getPhiChartLegendItems(
  labels: readonly string[] = DEFAULT_PHI_CHART_LEGEND_LABELS,
): ChartLegendItem[] {
  return labels.map((label) => ({
    label,
    color: getSeriesColorByLabel(label, DEFAULT_LINE_BAR_CHART_COLORS),
    shape: 'rectangle',
    size: 'small',
    decoration: isBudgetSeriesLabel(label) ? 'dash' : 'none',
    fontWeight: 'bold',
  }));
}
